import numpy as np

def one_partner_pairs(Pn, k):
    """Greedy from the closest: each share used at most once."""
    D = ssd_matrix(Pn)
    i, j = np.triu_indices(D.shape[0], 1)
    order = np.argsort(D[i, j], kind="stable")
    used, out = set(), []
    for o in order:
        a, b = int(i[o]), int(j[o])
        if a in used or b in used:
            continue
        out.append((a, b))
        used |= {a, b}
        if len(out) == k:
            break
    return out


def same_industry_share(pairs, ind):
    """Share of pairs inside one industry; 0.0 if there are none."""
    if not pairs:
        return 0.0
    return sum(1 for a, b in pairs if ind[a] == ind[b]) / len(pairs)
